import re
from docx import Document
from docx.shared import Pt, RGBColor, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1)
sec.top_margin = sec.bottom_margin = Inches(0.9)
st = doc.styles["Normal"]
st.font.name = "Calibri"; st.font.size = Pt(11)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Calibri")
for n, sz in (("Heading 1", 14), ("Heading 2", 12), ("Heading 3", 11)):
    s = doc.styles[n]; s.font.name = "Calibri"; s.font.size = Pt(sz); s.font.color.rgb = RGBColor(0x1F, 0x3A, 0x5F)

def runs(p, text, size=None):
    parts = re.split(r"(\*\*.+?\*\*|__.+?__)", text)
    for part in parts:
        if not part: continue
        if part.startswith("**"):
            r = p.add_run(part[2:-2]); r.bold = True
        elif part.startswith("__"):
            r = p.add_run(part[2:-2]); r.italic = True
        else:
            r = p.add_run(part)
        if size: r.font.size = Pt(size)
    return p

def P(text, size=None, align=None, after=6):
    p = doc.add_paragraph(); runs(p, text, size)
    p.paragraph_format.space_after = Pt(after)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    return p

def B(text, level=0):
    p = doc.add_paragraph(style="List Bullet" if level == 0 else "List Bullet 2"); runs(p, text)
    p.paragraph_format.space_after = Pt(3)
    return p

def N(text):
    p = doc.add_paragraph(style="List Number"); runs(p, text); p.paragraph_format.space_after = Pt(3); return p

def H(text, lvl=1):
    return doc.add_heading(text, level=lvl)

def shade(cell, hexcolor):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement("w:shd")
    shd.set(qn("w:val"), "clear"); shd.set(qn("w:color"), "auto"); shd.set(qn("w:fill"), hexcolor); tcPr.append(shd)

SEV = {"CRITICAL": "F4CCCC", "HIGH": "FCE5CD", "MEDIUM": "FFF2CC", "LOW": "D9EAD3"}

def T(headers, rows, widths=None, size=9):
    t = doc.add_table(rows=1, cols=len(headers)); t.style = "Table Grid"; t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""; r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(size)
        shade(c, "1F3A5F"); r.font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            lines = str(v).split("\n")
            for j, line in enumerate(lines):
                p = cells[i].paragraphs[0] if j == 0 else cells[i].add_paragraph()
                runs(p, line, size)
            if str(v).strip("*") in SEV: shade(cells[i], SEV[str(v).strip("*")])
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths): row.cells[i].width = Inches(w)
    doc.add_paragraph().paragraph_format.space_after = Pt(2)
    return t
